// exec deletes the rows, with their join table rows, in one transaction, and
// returns how many there were.
pub fn (b LoginDelete) exec() !int {
	return b.graph.client.delete(b.data)
}

// logins_by_keys returns the rows with the keys `keys`, in their order.
fn (g Graph) logins_by_keys(keys []string) ![]LoginNode {
	// as stored: no privacy rule or interceptor hides a row just written
	rows := Graph{
		client: g.client.bypass()
	}.logins().where(load.in_keys('id', keys, .int)).all()!
	mut by_key := map[string]LoginNode{}
	for row in rows {
		by_key[row.login.id.str()] = row
	}
	mut found := []LoginNode{cap: keys.len}
	for key in keys {
		found << by_key[key] or {
			return NotFoundError{
				table: 'logins'
			}
		}
	}
	return found
}

// CreateLoginInput is what a create of a `logins` row sets, as the GraphQL input
// `CreateLoginInput` gives it: `none` and empty lists leave things as
// they are.
pub struct CreateLoginInput {
pub mut:
	device_id ?string
	at        ?int
}

// set_input sets what `input` gives: clears first, then values, then edges.
pub fn (b LoginCreate) set_input(input CreateLoginInput) LoginCreate {
	mut next := b
	if v := input.device_id {
		next = next.set_device_id(v)
	}
	if v := input.at {
		next = next.set_at(v)
	}
	return next
}

// UpdateLoginInput is what a update of a `logins` row sets, as the GraphQL input
// `UpdateLoginInput` gives it: `none` and empty lists leave things as
